"""Bounded format checks on generated bytes, without evaluating their claims."""

import asyncio
import csv
import hashlib
import json
import zlib
from io import BytesIO, StringIO
from pathlib import PurePosixPath
from xml.etree import ElementTree
from zipfile import BadZipFile, ZipFile

from anyio.to_thread import run_sync

from app.core.exceptions import BadRequestError
from app.schemas.artifact_validation import ArtifactValidation

MAX_FILE = 2 * 1024**2
_slots = asyncio.Semaphore(2)
_OFFICE = {
    "docx": (
        "word/document.xml",
        "http://schemas.openxmlformats.org/wordprocessingml/2006/main",
        "document",
    ),
    "xlsx": (
        "xl/workbook.xml",
        "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
        "workbook",
    ),
    "pptx": (
        "ppt/presentation.xml",
        "http://schemas.openxmlformats.org/presentationml/2006/main",
        "presentation",
    ),
}


class ArtifactValidationError(BadRequestError):
    """The producer may fix this output; authorization failures remain separate."""


def office_package(content, suffix):
    """Inspect ZIP/XML without Office execution, extraction or external fetches."""
    main, namespace, root_name = _OFFICE[suffix]
    with ZipFile(BytesIO(content)) as archive:
        entries = archive.infolist()
        names = [entry.filename for entry in entries]
        if (
            len(entries) > 2048
            or len(names) != len(set(names))
            or sum(entry.file_size for entry in entries) > 16 * 1024**2
            or any(
                PurePosixPath(name).is_absolute()
                or ".." in PurePosixPath(name).parts
                or "\\" in name
                for name in names
            )
        ):
            raise ValueError("Package limits")
        roots = {}
        for entry in entries:
            data = archive.read(entry)  # CRC and actual decompression are checked here.
            if entry.filename.endswith((".xml", ".rels")):
                xml = data.decode("utf-8-sig")
                if "<!DOCTYPE" in xml.upper() or "<!ENTITY" in xml.upper():
                    raise ValueError("XML declarations")
                roots[entry.filename] = ElementTree.fromstring(xml)
        root = roots[main]
        if root.tag != f"{{{namespace}}}{root_name}":
            raise ValueError("Wrong Office format")
        types = roots["[Content_Types].xml"]
        if types.tag != "{http://schemas.openxmlformats.org/package/2006/content-types}Types":
            raise ValueError("Content types")
        if not any(node.get("PartName") == "/" + main for node in types):
            raise ValueError("Missing main part declaration")
        rels = roots["_rels/.rels"]
        if not any(
            node.get("Target", "").lstrip("/") == main
            and node.get("Type", "").endswith("/officeDocument")
            and node.get("TargetMode") != "External"
            for node in rels
        ):
            raise ValueError("Missing document relationship")
        if suffix == "docx" and root.find(f"{{{namespace}}}body") is None:
            raise ValueError("Missing body")
        if suffix == "xlsx" and not root.findall(f"{{{namespace}}}sheets/{{{namespace}}}sheet"):
            raise ValueError("Missing sheets")
    return ["office_zip_crc", "office_xml", "office_main_part"]


def reject_constant(value):
    raise ValueError("Non-finite JSON constant")


def bounded_json(text):
    depth, quoted, escaped = 0, False, False
    for char in text:
        if quoted:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                quoted = False
        elif char == '"':
            quoted = True
        elif char in "[{":
            depth += 1
            if depth > 128:
                raise ValueError("JSON nesting limit")
        elif char in "]}":
            depth -= 1
    json.loads(text, parse_constant=reject_constant)


def inspect_artifact(file):
    """Return only code-produced observations, never extracted user content."""
    stage = "字节完整性"
    try:
        content, name = file["content"], file["name"]
        if not isinstance(content, bytes) or len(content) > MAX_FILE:
            raise ValueError("Invalid bytes")
        if type(file["size"]) is not int or len(content) != file["size"]:
            raise ValueError("Invalid size")
        digest = hashlib.sha256(content).hexdigest()
        if file["sha256"] != digest:
            raise ValueError("Invalid digest")
        checks, structure = ["size", "sha256"], "not_checked"
        suffix = name.rsplit(".", 1)[-1].lower()
        if suffix in {"md", "txt", "csv", "json"}:
            stage = "UTF-8 编码"
            text = content.decode("utf-8-sig")
            checks.append("utf8")
            structure = "checked"
            if suffix == "json":
                stage = "JSON 语法(不允许 NaN/Infinity，最多 128 层)"
                bounded_json(text)
                checks.extend(["json_syntax", "json_depth"])
            elif suffix == "csv":
                stage = "CSV 引号结构"
                try:
                    for _ in csv.reader(StringIO(text, newline=""), strict=True):
                        pass
                    checks.append("csv_syntax")
                except csv.Error as exc:
                    # Python's process-wide field limit must not be raised for one file.
                    if "field larger than field limit" not in str(exc):
                        raise
                    structure = "not_checked"
                    checks.append("csv_field_limit_reached")
        elif suffix in _OFFICE:
            stage = "Office 包结构"
            checks.extend(office_package(content, suffix))
            structure = "checked"
        return ArtifactValidation(
            sha256=digest, size=len(content), structure=structure, checks=checks
        ).model_dump(mode="json")
    except (
        KeyError,
        TypeError,
        ValueError,
        RecursionError,
        csv.Error,
        BadZipFile,
        OSError,
        zlib.error,
        ElementTree.ParseError,
        RuntimeError,
        NotImplementedError,
    ) as exc:
        raise ArtifactValidationError(message=f"产物{stage}校验失败，请修正内容后重新生成") from exc


async def validate_files(files):
    if len(files) > 10 or len({file["name"] for file in files}) != len(files):
        raise ArtifactValidationError(message="每次最多保存 10 个文件，名称不能重复")
    async with _slots:
        return await run_sync(lambda: [inspect_artifact(file) for file in files])
